-- ingredientes y preparacion son TEXT (diccionario); la API guarda en ellos JSON.
INSERT INTO receta (idUsuario, idEstado, nombreReceta, descripcion, ingredientes, preparacion,
                    estadoValidacion, urlImagen, fechaRegistro) VALUES
 (2, 20, 'Mole amarillo de pollo',
  'Un mole de cazuela, con el aroma de la hierba santa y la textura suave de la masa. Así lo preparamos en mi casa para compartir a la hora de la comida.',
  '[{"cantidad": "700", "unidad": "g", "nombre": "pollo en piezas"}, {"cantidad": "4", "unidad": "piezas", "nombre": "chiles guajillo, sin semillas"}, {"cantidad": "300", "unidad": "g", "nombre": "jitomate"}, {"cantidad": "200", "unidad": "g", "nombre": "tomate verde, sin cáscara"}, {"cantidad": "½", "unidad": "pieza", "nombre": "cebolla blanca"}, {"cantidad": "2", "unidad": "dientes", "nombre": "ajo"}, {"cantidad": "1", "unidad": "pieza", "nombre": "chayote, en cubos"}, {"cantidad": "150", "unidad": "g", "nombre": "ejotes, sin puntas"}, {"cantidad": "80", "unidad": "g", "nombre": "masa de maíz nixtamalizado"}, {"cantidad": "1", "unidad": "litro", "nombre": "caldo de pollo"}, {"cantidad": "1", "unidad": "hoja", "nombre": "hierba santa"}, {"cantidad": "2", "unidad": "cucharadas", "nombre": "aceite vegetal"}, {"cantidad": "¼", "unidad": "cucharadita", "nombre": "comino molido"}, {"cantidad": "1", "unidad": "pizca", "nombre": "clavo molido"}, {"cantidad": "Al gusto", "unidad": "", "nombre": "sal"}]',
  '{"pasos": [{"titulo": "Prepara los ingredientes", "texto": "Lava los vegetales. Corta el chayote en cubos de 2 cm y los ejotes a la mitad. Retira tallos, semillas y venas de los chiles; tuéstalos unos segundos por lado en un comal, sin quemarlos. Remójalos 15 minutos en agua caliente."}, {"titulo": "Cuece el pollo y las verduras", "texto": "Pon el pollo en una olla con el litro de caldo. Lleva a hervor suave y cocina tapado de 30 a 35 minutos. Agrega el chayote cuando hayan pasado 15 minutos y los ejotes en los últimos 10 minutos. El pollo debe quedar bien cocido; si usas termómetro, el centro debe alcanzar 74 °C. Reserva el caldo."}, {"titulo": "Muele la base del mole", "texto": "Mientras se cuece el pollo, asa el jitomate, el tomate verde, la cebolla y el ajo en el comal hasta que se suavicen. Licúa con los chiles escurridos, el comino, el clavo y una taza del caldo de cocción. Cuela para obtener una salsa tersa."}, {"titulo": "Sazona la salsa", "texto": "Calienta el aceite en una cazuela a fuego medio. Vierte la salsa con cuidado y cocina de 8 a 10 minutos, moviendo para que no se pegue. Añade poco a poco el resto del caldo reservado y mezcla."}, {"titulo": "Espesa con la masa", "texto": "Disuelve la masa en ½ taza de agua hasta que no tenga grumos. Incorpórala en un hilo a la salsa mientras mueves. Agrega la hoja de hierba santa y cocina a fuego bajo de 8 a 10 minutos. Si espesa demasiado, añade un poco de agua caliente."}, {"titulo": "Integra y sirve", "texto": "Devuelve el pollo, el chayote y los ejotes a la cazuela. Cocina todo junto 5 minutos y ajusta la sal. Retira la hoja de hierba santa. Sirve caliente con tortillas de maíz recién hechas."}], "porciones": 4, "tiempoTotal": 60, "dificultad": "Intermedia", "tipoPlatillo": "Plato fuerte", "region": "Valles Centrales", "localidad": "San Pablo Villa de Mitla", "municipio": "San Pablo Villa de Mitla", "cveMun": "20298", "latitud": 16.9214, "longitud": -96.3594, "consejo": "Agrega la masa poco a poco y no dejes de mover. El amarillo debe quedar ligero, no como un atole espeso.", "historia": "Aprendí a preparar este amarillo acompañando a mi mamá al mercado de Mitla. Ella elegía los ejotes tiernos y siempre guardaba una hoja de hierba santa para la cazuela. En nuestra casa lo comemos con tortillas; a veces cambiamos las verduras por las que hay en temporada.", "pieFoto": "Una versión familiar con pollo, chayote, ejotes y hierba santa."}',
  'validada', '/assets/img/mole-amarillo-servido.jpg', NOW() - INTERVAL 1 HOUR),
 (2, 20, 'Tlayudas con tasajo',
