INSERT INTO comentario (idReceta, idUsuario, comentario) VALUES
 (1, 3, 'Lo preparé el domingo con la hoja santa del mercado y quedó delicioso. ¡Gracias por compartirlo!'),
 (1, 20, 'Mi abuela también le ponía chayote. Gracias por guardar esta receta.'),
 (12, 21, 'Lo hicimos para la boda de mi prima siguiendo sus pasos. ¡Quedó idéntico al de la familia!'),
 (19, 20, '¿Se puede usar pavo de granja? Aquí no consigo pavo de traspatio.');
